-- 0035 app2 E3: helpers + dual RLS (migration-map.md section 2, step 3). PENDING: staging first, then prod. Needs 0033, 0034.
-- GENERATED by test/gen_e3.py from a post-0032 prod-shape database (before 0033); regenerate, do not hand-edit.
--   * app.is_member(ws) / app.has_role(ws, roles): SECURITY DEFINER, STABLE, empty search_path (same bodies as app2 0001),
--     executable by authenticated only.
--   * member policies on app.workspaces / app.memberships (read your own workspace).
--   * every owner policy on the 42 tenant tables ({N} of them, on {TN} tables) becomes  <old expression> OR (select app.is_member(workspace_id)).
--     Same name, command and role (authenticated), so the live app keeps reading and writing as the owner exactly as before.
--   * owner policies on tables without workspace_id ({NOWN}: {OWNT}) stay owner-only, untouched.
--   * the {W} ari_worker policies (TO ari_worker USING true) are not touched; ari_worker gets nothing on schema app.
-- Effective access today is unchanged: the only member is the owner, who already passes is_owner(). The OR clause is
-- dropped in C1, after app2 parity.
-- Locks: the precheck and the helpers touch no public table. Then ONE SHORT TRANSACTION PER TABLE swaps that table's policies
--   (drop + create in the same transaction, so the table is never without its policy; ACCESS EXCLUSIVE for milliseconds),
--   each with lock_timeout 5s + statement_timeout 60s. A busy table stops the request cleanly; re-run to finish.
--   The ledger row is written last, only when all {N} owner policies carry the member clause.
-- Run: the whole file as ONE request (Management API query endpoint) or psql -v ON_ERROR_STOP=1 -f. See README.md.
-- Rollback: 0035_app2_e3_dual_rls_rollback.sql (same folder) restores each policy verbatim.

-- ---------- precheck: the target has exactly the policy shape this file was generated from (else stop; regenerate) ----------
begin;
set local lock_timeout = '5s';
set local statement_timeout = '60s';
do $$
declare n int;
begin
  if not exists (select 1 from supabase_migrations.schema_migrations where version = '0034') then
    raise exception '0035 precheck: 0034 (app2 E2) is not applied';
  end if;
  select count(*) into n from pg_policies where schemaname = 'public' and roles = '{authenticated}'
    and (coalesce(qual, '') || coalesce(with_check, '')) like '%is_owner()%';
  if n <> {NALL} then raise exception '0035 precheck: expected {NALL} owner policies on public, found %', n; end if;
  select count(*) into n from pg_policies where schemaname = 'public' and roles = '{authenticated}' and tablename = any({ARR})
    and (coalesce(qual, '') || coalesce(with_check, '')) like '%is_owner()%';
  if n <> {N} then raise exception '0035 precheck: expected {N} owner policies on the 42 tenant tables, found %', n; end if;
  select count(*) into n from pg_policies where schemaname = 'public' and roles <> '{authenticated}' and roles <> '{ari_worker}';
  if n <> 0 then raise exception '0035 precheck: % policies for roles other than authenticated/ari_worker', n; end if;
end $$;
commit;

-- ---------- helpers + app.* member policies (no lock on any public table) ----------
begin;
set local lock_timeout = '5s';
set local statement_timeout = '60s';
create or replace function app.is_member(ws uuid) returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from app.memberships m
                 where m.workspace_id = ws and m.user_id = auth.uid() and m.status = 'active')
$$;
create or replace function app.has_role(ws uuid, roles app.role_t[]) returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from app.memberships m
                 where m.workspace_id = ws and m.user_id = auth.uid() and m.status = 'active' and m.role = any(roles))
$$;
revoke all on function app.is_member(uuid), app.has_role(uuid, app.role_t[]) from public, anon;
grant execute on function app.is_member(uuid), app.has_role(uuid, app.role_t[]) to authenticated;

drop policy if exists ws_read on app.workspaces;
create policy ws_read on app.workspaces for select to authenticated using ((select app.is_member(id)));
drop policy if exists own_or_ws_read on app.memberships;
create policy own_or_ws_read on app.memberships for select to authenticated using ((select app.is_member(workspace_id)));
commit;
